package com.datalogger;

import static com.datalogger.constants.PluginConstants.CONFIG_GROUP;
import static com.datalogger.constants.PluginConstants.NO_MIGRATION_CONFIG_KEY;
import static com.datalogger.constants.PluginConstants.PLUGIN_VERSION_CONFIG_KEY;
import com.datalogger.models.enums.ColosseumBroadcastMode;
import com.datalogger.models.enums.ExchangeLoggerCsvFileStrategy;
import com.datalogger.models.enums.ExchangeLoggerJsonFileStrategy;
import com.datalogger.models.enums.ScreenshotFormat;
import com.datalogger.models.enums.TimestampFormat;
import com.datalogger.models.enums.UIScrollSpeed;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;


@ConfigGroup(CONFIG_GROUP)
public interface DataLoggerConfig extends Config {

	// --- Sections ---

	@ConfigSection(
		name = "Side bar panel",
		description = "Configurations related to the sidebar panel",
		position = 0,
		closedByDefault = true
	)
	String SIDE_BAR_PANEL_SECTION = "sideBarPanelSection";

	@ConfigSection(
		name = "Item loggers",
		description = "Settings related to item loggers",
		position = 1,
		closedByDefault = true
	)
	String ITEM_LOGGER_SECTION = "itemLogger";

	@ConfigSection(
		name = "Grand Exchange",
		description = "Settings related to the Grand Exchange loggers",
		position = 2,
		closedByDefault = true
	)
	String GE_LOGGER_SECTION = "geLogger";

	@ConfigSection(
		name = "Colosseum",
		description = "Settings for Fortis Colosseum trial logging",
		position = 3,
	closedByDefault = true
	)
	String COLOSSEUM_SECTION = "colosseum";

	@ConfigSection(
		name = "Colosseum timeline logger",
		description = "Settings related to Fortis Colosseum trial timeline logging",
		position = 4,
		closedByDefault = true
	)
	String COLOSSEUM_TIMELINE_SECTION = "colosseumTimeline";

	@ConfigSection(
		name = "Screenshots",
		description = "Settings for automatic screenshot capturing",
		position = 6,
		closedByDefault = true
	)
	String SCREENSHOT_SECTION = "screenshot";

	@ConfigSection(
		name = "Discord",
		description = "Configurations related to Discord",
		position = 7,
		closedByDefault = true
	)
	String DISCORD_SECTION = "discord";

	@ConfigSection(
		name = "Discord pre-defined template",
		description = "Configurations related to customizing pre-defined Discord template configurations",
		position = 8,
		closedByDefault = true
	)
	String PREDEFINED_TEMPLATE_DISCORD_SECTION = "predefinedTemplateDiscordSection";

	@ConfigSection(
		name = "Discord custom template",
		description = "Configurations related to customizable Discord template configurations",
		position = 9,
		closedByDefault = true
	)
	String CUSTOM_TEMPLATE_DISCORD_SECTION = "customTemplateDiscordSection";

	// --- Side Bar Items ---

	@ConfigItem(
		keyName = "showSideBarPanel",
		name = "Show side bar panel",
		description = "If enabled, show the sidebar.",
		position = 0,
		section = SIDE_BAR_PANEL_SECTION
	)
	default boolean showSideBarPanel() { return true; }

	@ConfigItem(
		keyName = "allowOuterScrollbar",
		name = "Allow outer sidepanel scrollbar",
		description = "If enabled, the sidepanel has a scrollbar, allowing you to view more data at once.",
		position = 1,
		section = SIDE_BAR_PANEL_SECTION
	)
	default boolean allowOuterScrollbar() { return true; }

	@ConfigItem(
		keyName = "outerScrollSpeed",
		name = "Outer scroll speed",
		description = "Tweaks the scroll speed of the outer scroll bar in the sidebar panel (if present).",
		position = 2,
		section = SIDE_BAR_PANEL_SECTION
	)
	default UIScrollSpeed outerScrollSpeed() { return UIScrollSpeed.HIGH; }

	@ConfigItem(
		keyName = "innerScrollSpeed",
		name = "Inner scroll speed",
		description = "Tweaks the scroll speed of the inner scroll bar in the sidebar panel.",
		position = 3,
		section = SIDE_BAR_PANEL_SECTION
	)
	default UIScrollSpeed innerScrollSpeed() { return UIScrollSpeed.MEDIUM; }

	@ConfigItem(
		keyName = "hideZeroPriceItems",
		name = "Exclude 0 price items",
		description = "If enabled, exclude items from the item viewer with a price of 0.",
		position = 4,
		section = SIDE_BAR_PANEL_SECTION
	)
	default boolean hideZeroPriceItems() { return true; }

	// --- Item Logger ---

	@ConfigItem(
		keyName = "logItemVault",
		name = "Log item data",
		description = "If enabled, item data is stored internally if data is accessible.",
		position = 3,
		section = ITEM_LOGGER_SECTION
	)
	default boolean logItemVault() { return true; }

	@ConfigItem(
		keyName = "logItemVaultCSV",
		name = "Log item data (CSV)",
		description = "If enabled, a copy of the internal (aggregated) item data is exported as CSV files.",
		position = 4,
		section = ITEM_LOGGER_SECTION
	)
	default boolean logItemVaultCSV() { return true; }

	@ConfigItem(
		keyName = "logItemVaultJSON",
		name = "Log item data (JSON)",
		description = "If enabled, a copy of the internal (aggregated) item data is exported as JSON files.",
		position = 5,
		section = ITEM_LOGGER_SECTION
	)
	default boolean logItemVaultJSON() { return true; }

	@ConfigItem(
		keyName = "skipItemVaultAccountList",
		name = "Exclude accounts",
		description = "Accounts that should not be included by the Item data logger. Accounts should be separated using ','; e.g. ACCOUNT_NAME,OTHER_ACCOUNT_NAME",
		position = 6,
		section = ITEM_LOGGER_SECTION
	)
	default String skipItemVaultAccountList() { return ""; }

	// --- Grand Exchange Items ---

	@ConfigItem(
		keyName = "logGrandExchange",
		name = "Log Grand Exchange",
		description = "If enabled, Grand Exchange offers are logged upon completion.",
		position = 0,
		section = GE_LOGGER_SECTION
	)
	default boolean logGrandExchange() { return true; }

	@ConfigItem(
		keyName = "geJsonFileStrategy",
		name = "JSON File Strategy",
		description = "Determines the file format and rotation for GE JSON logs, if any",
		position = 1,
		section = GE_LOGGER_SECTION
	)
	default ExchangeLoggerJsonFileStrategy geJsonFileStrategy()
	{
		return ExchangeLoggerJsonFileStrategy.JSON_SINGLE;
	}

	@ConfigItem(
		keyName = "geCsvFileStrategy",
		name = "CSV File Strategy",
		description = "Determines the file format and rotation for GE CSV logs, if any",
		position = 2,
		section = GE_LOGGER_SECTION
	)
	default ExchangeLoggerCsvFileStrategy geCsvFileStrategy()
	{
		return ExchangeLoggerCsvFileStrategy.NONE;
	}

	// --- Grand Exchange Entry Value Toggles ---

	@ConfigItem(
		keyName = "geIncludeItemId",
		name = "Include Item ID",
		description = "Include the item's ID in the logged JSON entry.",
		position = 3,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeItemId() { return true; }

	@ConfigItem(
		keyName = "geIncludeItemName",
		name = "Include Item Name",
		description = "Include the item name in the logged JSON entry.",
		position = 4,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeItemName() { return true; }

	@ConfigItem(
		keyName = "geIncludeIsBuy",
		name = "Include Trade Type (Buy/Sell)",
		description = "Include whether the offer was a buy or sell in the logged JSON entry.",
		position = 5,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeIsBuy() { return true; }

	@ConfigItem(
		keyName = "geIncludeQuantity",
		name = "Include Quantity",
		description = "Include the traded quantity in the logged JSON entry.",
		position = 6,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeQuantity() { return true; }

	@ConfigItem(
		keyName = "geIncludePrice",
		name = "Include Price",
		description = "Include the price per item in the logged JSON entry.",
		position = 7,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludePrice() { return true; }

	@ConfigItem(
		keyName = "geIncludeValue",
		name = "Include Total Value",
		description = "Include the total value (gp) in the logged JSON entry.",
		position = 8,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeValue() { return true; }

	@ConfigItem(
		keyName = "geIncludeTax",
		name = "Include Tax",
		description = "Include the GE tax paid in the logged JSON entry.",
		position = 9,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeTax() { return true; }

	@ConfigItem(
		keyName = "geIncludeAccountName",
		name = "Include Account Name",
		description = "Include the player's account name in the logged JSON entry.",
		position = 10,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeAccountName() { return true; }

	@ConfigItem(
		keyName = "geIncludeAccountHash",
		name = "Include Account Hash",
		description = "Include the player's account hash in the logged JSON entry.",
		position = 11,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeAccountHash() { return true; }

	@ConfigItem(
		keyName = "geIncludeGeSlot",
		name = "Include GE Slot",
		description = "Include the Grand Exchange slot index in the logged JSON entry.",
		position = 12,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeGeSlot() { return true; }

	@ConfigItem(
		keyName = "geIncludeIsCancelled",
		name = "Include Is Cancelled",
		description = "Include whether the offer was cancelled in the logged JSON entry.",
		position = 14,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeIsCancelled() { return true; }

	@ConfigItem(
		keyName = "geIncludeOfferCreationTime",
		name = "Include Offer Creation Time",
		description = "Include the offer creation timestamp in the logged JSON entry.",
		position = 15,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeOfferCreationTime() { return true; }

	@ConfigItem(
		keyName = "geIncludeExactTimestamp",
		name = "Include Exact Timestamp",
		description = "Include the exact completion timestamp in the logged JSON entry.",
		position = 16,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeExactTimestamp() { return true; }

	@ConfigItem(
		keyName = "geIncludeOriginalOfferQuantity",
		name = "Include Original Offer Quantity",
		description = "Include the originally offered quantity in the logged JSON entry.",
		position = 18,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeOriginalOfferQuantity() { return true; }

	@ConfigItem(
		keyName = "geIncludeOriginalOfferPrice",
		name = "Include Original Offer Price",
		description = "Include the originally offered price in the logged JSON entry.",
		position = 19,
		section = GE_LOGGER_SECTION
	)
	default boolean geIncludeOriginalOfferPrice() { return true; }


	// --- Colosseum Items ---

	@ConfigItem(
		keyName = "logColosseum",
		name = "Log Colosseum Trials",
		description = "If enabled, Fortis Colosseum trials are logged.",
		position = 0,
		section = COLOSSEUM_SECTION
	)
	default boolean logColosseum() { return true; }


	@ConfigItem(
		keyName = "logColosseumCSV",
		name = "Log Colosseum Trials (CSV)",
		description = "If enabled, Fortis Colosseum waves are also logged in a CSV file.",
		position = 1,
		section = COLOSSEUM_SECTION
	)
	default boolean logColosseumCSV() { return true; }

	@ConfigItem(
		keyName = "logQuiverAsSplinters",
		name = "Log quiver reward as splinters",
		description = "If enabled, the Dizana's quiver (uncharged) reward is logged as 4,000 Sunfire splinters instead.",
		position = 2,
		section = COLOSSEUM_SECTION
	)
	default boolean logQuiverAsSplinters() { return false; }

	@ConfigItem(
		keyName = "screenshotBetweenWaves",
		name = "Take Colosseum screenshots",
		description = "Automatically take a screenshot after a wave ends, when the chest UI is visible, or when you die.",
		position = 3,
		section = COLOSSEUM_SECTION
	)
	default boolean screenshotBetweenWaves() { return false; }

	@ConfigItem(
		keyName = "colosseumTag",
		name = "Tag",
		description = "Custom tag(s) that will be assigned to logged entries and can be used as filter in the dataviewer. Separate multiple tags with '|'",
		position = 4,
		section = COLOSSEUM_SECTION
	)
	default String colosseumTag() { return ""; }

	@ConfigItem(
		keyName = "autoMergeWaveLogs",
		name = "Auto merge wave logs",
		description = "Automatically merge all wave log files after an attempt is completed.",
		position = 5,
		section = COLOSSEUM_SECTION
	)
	default boolean autoMergeWaveLogs() { return false; }

	@ConfigItem(
		keyName = "trackSupplies",
		name = "Track supply/ammo consumption",
		description = "Track supplies and ammo consumed during a Colosseum attempt",
		position = 6,
		section = COLOSSEUM_SECTION
	)
	default boolean trackSupplies() { return true; }

	// --- Colosseum NPC Optional Items ---

	@ConfigItem(
		keyName = "logWaveTimeline",
		name = "Log Colosseum wave timeline",
		description = "If enabled, player- and NPC- data is logged every game tick during waves and added to a timeline.",
		position = 0,
		section = COLOSSEUM_TIMELINE_SECTION
	)
	default boolean logWaveTimeline() { return true; }

	@ConfigItem(
		keyName = "logTimestamp",
		name = "Log Timestamp",
		description = "Select the format of the timestamp added to the timeline data, if any.",
		position = 1,
		section = COLOSSEUM_TIMELINE_SECTION
	)
	default TimestampFormat logTimestamp() {
		return TimestampFormat.NONE;
	}

	@ConfigItem(
		keyName = "logFremenniks",
		name = "Track Fremenniks",
		description = "Include Fremennik warband NPC data in the timeline",
		position = 2,
		section = COLOSSEUM_TIMELINE_SECTION
	)
	default boolean logFremenniks() { return false; }

	@ConfigItem(
		keyName = "logSolarFlare",
		name = "Track Solar Flares",
		description = "Include Solarflare locations in timeline data",
		position = 3,
		section = COLOSSEUM_TIMELINE_SECTION
	)
	default boolean logSolarFlare() { return false; }

	@ConfigItem(
		keyName = "logHealingTotem",
		name = "Track Healing Totems",
		description = "Include Healing totem locations in timeline data",
		position = 4,
		section = COLOSSEUM_TIMELINE_SECTION
	)
	default boolean logHealingTotem() { return false; }

	@ConfigItem(
		keyName = "logBeeSwarm",
		name = "Track Bee Swarms",
		description = "Include Bee Swarm locations in timeline data",
		position = 5,
		section = COLOSSEUM_TIMELINE_SECTION
	)
	default boolean logBeeSwarm() { return false; }

	@ConfigItem(
		keyName = "logBeamCrystal",
		name = "Track Beam Crystals",
		description = "Include Beam Crystal locations during wave 12 in timeline data",
		position = 6,
		section = COLOSSEUM_TIMELINE_SECTION
	)
	default boolean logBeamCrystal() { return false; }

	// --- Screenshot Items ---

	@ConfigItem(
		keyName = "screenshotFormat",
		name = "Screenshot format",
		description = "Select the file format for screenshots. PNG is lossless quality, JPEG reduces file size.",
		position = 0,
		section = SCREENSHOT_SECTION
	)
	default ScreenshotFormat screenshotFormat() {
		return ScreenshotFormat.PNG;
	}

	// --- Discord ---


	@ConfigItem(
		keyName = "enableDiscordBroadcasting",
		name = "Enable Discord broadcasting",
		description = "Uncheck to manually disable Discord broadcasting without altering other configurations.",
		position = 0,
		section = DISCORD_SECTION
	)
	default boolean enableWebhookBroadcasting() { return true; }

	@ConfigItem(
		keyName = "colosseumDiscordWebhookUrl",
		name = "Colosseum webhook URL",
		description = "The Discord Webhook URL used to broadcast completed Colosseum runs. Separate multiple URLs with a ','.",
		position = 2,
		section = DISCORD_SECTION
	)
	default String colosseumDiscordWebhookUrl()
	{
		return "";
	}

	@ConfigItem(
		keyName = "broadcastCompletedTrials",
		name = "Completed",
		description = "How to broadcast a completed trial after opening the chest rewards UI.",
		position = 3,
		section = DISCORD_SECTION
	)
	default ColosseumBroadcastMode broadcastCompletedTrials() { return ColosseumBroadcastMode.SKIP; }

	@ConfigItem(
		keyName = "broadcastCancelledTrials",
		name = "Cancelled",
		description = "How to broadcast a cancelled trial after opening the chest rewards UI",
		position = 4,
		section = DISCORD_SECTION
	)
	default ColosseumBroadcastMode broadcastCancelledTrials() { return ColosseumBroadcastMode.SKIP; }

	@ConfigItem(
		keyName = "broadcastFailedTrials",
		name = "Failed",
		description = "How to broadcast a failed trial after taking lethal damage",
		position = 5,
		section = DISCORD_SECTION
	)
	default ColosseumBroadcastMode broadcastFailedTrials() { return ColosseumBroadcastMode.SKIP; }

	@Range(min = 0)
	@ConfigItem(
		keyName = "broadcastRewardThreshold",
		name = "Min. reward (k)",
		description = "Reward value threshold (* 1000 gp) for broadcasting a finished trial",
		position = 6,
		section = DISCORD_SECTION
	)
	default int broadcastRewardThreshold()
	{
		return 0;
	}

	@Range(min=1, max=12)
	@ConfigItem(
		keyName = "broadcastWaveThreshold",
		name = "Min. wave (1-12)",
		description = "Only broadcast finished trials if they reached at least this wave",
		position = 7,
		section = DISCORD_SECTION
	)
	default int broadcastWaveThreshold() {
		return 10;
	}

	@ConfigItem(
		keyName = "broadcastStatus",
		name = "Include status",
		description = "Include status in pre-defined templates",
		position = 0,
		section = PREDEFINED_TEMPLATE_DISCORD_SECTION
	)
	default boolean includeStatus() { return true; }

	@ConfigItem(
		keyName = "broadcastTime",
		name = "Include completion time",
		description = "Include completion time in pre-defined templates",
		position = 1,
		section = PREDEFINED_TEMPLATE_DISCORD_SECTION
	)
	default boolean includeTime() { return true; }

	@ConfigItem(
		keyName = "broadcastReward",
		name = "Include reward",
		description = "Include the item reward in pre-defined templates",
		position = 2,
		section = PREDEFINED_TEMPLATE_DISCORD_SECTION
	)
	default boolean includeReward() { return true; }

	@ConfigItem(
		keyName = "broadcastModifiers",
		name = "Include modifiers",
		description = "Include active/chosen modifiers in pre-defined templates",
		position = 3,
		section = PREDEFINED_TEMPLATE_DISCORD_SECTION
	)
	default boolean includeModifiers() { return true; }

	@ConfigItem(
		keyName = "broadcastGlory",
		name = "Include glory",
		description = "Include earned glory in pre-defined templates",
		position = 4,
		section = PREDEFINED_TEMPLATE_DISCORD_SECTION
	)
	default boolean includeGlory() { return true; }

	@ConfigItem(
		keyName = "broadcastRewardValue",
		name = "Include reward value",
		description = "Include the total reward value (gp) in pre-defined templates",
		position = 5,
		section = PREDEFINED_TEMPLATE_DISCORD_SECTION
	)
	default boolean includeRewardValue() { return true; }

	@ConfigItem(
		keyName = "broadcastSupplyValue",
		name = "Include supply value",
		description = "Include the consumed supplies value (gp) in pre-defined templates",
		position = 6,
		section = PREDEFINED_TEMPLATE_DISCORD_SECTION
	)
	default boolean includeSupplyValue() { return true; }

	@ConfigItem(
		keyName = "colosseumCustomTemplate",
		name = "Customizable template",
		description = "Define a custom template to broadcast",
		position = 0,
		section = CUSTOM_TEMPLATE_DISCORD_SECTION
	)
	default String colosseumCustomTemplate()
	{
		return "# --- INSTRUCTIONS --- \n" +
			"# Edit this text to format your Discord webhook.\n" +
			"# Global: <PLAYER>, <RESULT>, <TOTAL_GLORY>, <TIME>\n" +
			"# Wave-specific: <1:MOD>, <12:TIME>, <6:STATUS>\n" +
			"# Use 'Test Colosseum Discord webhook' button in side panel to preview template!\n" +
			"# See Custom Template Keywords section at https://runelite.net/plugin-hub/show/data-logger for a complete list of keywords\n" +
			"# You can also quickly test various templates in the utilities section of the sidebar panel\n" +
			"# --------------------\n" +
			"**<PLAYER>** just finished a Colosseum run!\n" +
			"**Result:** <RESULT>\n" +
			"**Time:** <TIME>\n" +
			"**Final Modifier:** <12:MOD>\n\n\n\n\n";
	}

	@ConfigItem(
		keyName = PLUGIN_VERSION_CONFIG_KEY,
		name = "Last Notified Version",
		description = "Internal tracker for update notifications",
		hidden = true
	)
	default String lastNotifiedVersion() {
		return "";
	}

	@ConfigItem(
		keyName = NO_MIGRATION_CONFIG_KEY,
		name = "Has refused Colosseum data migration",
		description = "Internal flag that is set if the user wishes not to migrate",
		hidden = true
	)
	default boolean hasRefusedMigration() {
		return false;
	}
}

