package com.datalogger.framework;

import com.datalogger.DataLoggerConfig;
import com.datalogger.events.AccountSessionStarted;
import com.datalogger.models.enums.GameMode;
import com.datalogger.services.FileIOService;
import java.io.File;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Slf4j
public abstract class AbstractLogger implements Loggable {
	@Inject protected Client client;
	@Inject protected FileIOService fileIOService;
	@Inject protected DataLoggerConfig config;

	// Currently active account
	private boolean onRegularWorld = false;
	private GameMode gameMode = null;
	private String accountName = "unknown";
	private String accountHashString = "-1";
	private long accountHashLong = -1;

	/**
	 * Logic for getting an account name, which is used as a folder in the file structure
	 */
	protected String getAccountName() {
		return accountName;
	}

	/**
	 * A numerical hash string associated with the OSRS account.
	 */
	protected String getAccountHashString() {
		return accountHashString;
	}

	/**
	 * A numerical hash string associated with the OSRS account.
	 */
	protected long getAccountHashLong() {
		return accountHashLong;
	}

	/**
	 * Returns true if the current session is on a temporary game mode like leagues
	 */
	protected boolean isOnRegularWorld()
	{
		return onRegularWorld;
	}

	/**
	 * Return the GameMode of the current world
	 */
	protected GameMode getGameMode()
	{
		return gameMode;
	}

	/**
	 * Centralized write method that every sub-logger will use.
	 * It automatically resolves the target file based on the logger type.
	 */
	protected void logRow(String csvRow, File csvFile) {
		if (!isEnabled() || accountName.equals("unknown")) {
			return;
		}

//		File logFile = fileIOService.getTargetFile(getLogType());
		fileIOService.atomicWrite(csvFile, getCsvHeader(), csvRow);
	}

	/**
	 * Listens for our custom global session event.
	 * This guarantees the hash and name are valid, and it runs on the ClientThread.
	 */
	@Subscribe
	public void onAccountSessionStarted(AccountSessionStarted event) {
		accountName = event.getAccountName();
		accountHashString = event.getAccountHashString();
		accountHashLong = event.getAccountHash();
		onRegularWorld = event.isOnRegularWorld();
		gameMode = event.getGameMode();

		log.debug("[{}] Session initialized for {} ({})", getLogType(), accountName, accountHashString);

		if (isEnabled()) {
			setup();
		}
	}

	/**
	 * Resets account hash and cache
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGIN_SCREEN) {
			accountName = "unknown";
			accountHashString = "-1";
		}
	}

	/**
	 * Removes OSRS '@' formatted tags (e.g. @mes_hl_red@, @blu@, @cr1@) from a message.
	 * Highly optimized to prevent regex overhead and zero-allocation fast-failing.
	 */
	protected static String preprocessMessage(String message) {
		if (message == null) {
			return null;
		}

		String tagsRemoved = Text.removeTags(message);

		if (tagsRemoved.indexOf('@') == -1) {
			return tagsRemoved;
		}

		StringBuilder sb = new StringBuilder(tagsRemoved.length());
		int currentIndex = 0;

		while (currentIndex < tagsRemoved.length()) {
			int start = tagsRemoved.indexOf('@', currentIndex);
			if (start == -1) {
				sb.append(tagsRemoved, currentIndex, tagsRemoved.length());
				break;
			}

			int end = tagsRemoved.indexOf('@', start + 1);
			if (end == -1) {
				sb.append(tagsRemoved, currentIndex, tagsRemoved.length());
				break;
			}

			boolean isTag = (end > start + 1);
			for (int i = start + 1; i < end; i++) {
				char c = tagsRemoved.charAt(i);
				if (!Character.isLetterOrDigit(c) && c != '_') {
					isTag = false;
					break;
				}
			}

			if (isTag) {
				sb.append(tagsRemoved, currentIndex, start);
				currentIndex = end + 1;
			} else {
				sb.append(tagsRemoved, currentIndex, start + 1);
				currentIndex = start + 1;
			}
		}

		return sb.toString();
	}
}

