		String accountHash = String.valueOf(entry.getAccountHash());

		File jsonlFile = INTERNAL_LEDGER_CACHE.computeIfAbsent(accountHash, hash -> {
			File dir = INTERNAL_GE_OFFERS_DIR;
			if (!dir.exists())
			{
				dir.mkdirs();
