	{
		return new String[] {
			CHECK_PREFIX,
			UPDATE_PREFIX,
			CHARGE_PREFIX
		};
	}

	@Override
	protected Integer parseChargeCount(String message)
	{
		if (message.startsWith(CHECK_PREFIX))
		{
			int endIndex = message.indexOf(" charges left", CHECK_PREFIX.length());
			if (endIndex != -1)
