@Slf4j
public class DataLoggerPanel extends PluginPanel {

	private final CardLayout cardLayout;
	private final JPanel cardContainer;
	private final JScrollPane scrollPane;
	private final JScrollBar scrollBar;

	private final UtilitiesModePanel utilitiesPanel;
	private final ColosseumStatisticsModePanel colosseumPanel;
	private final ItemsModePanel itemsPanel;
	private final ItemsManagerModePanel itemsManagerPanel;
	private final WebhookTestModePanel webhookTestModePanel;

	@Inject
	public DataLoggerPanel(
		UtilitiesModePanel utilitiesPanel,
		ColosseumStatisticsModePanel colosseumPanel,
//     ColosseumReviewModePanel colosseumReviewPanel,
		ItemsModePanel itemsPanel,
		ItemsManagerModePanel itemsManagerPanel,
		DataLoggerConfig config, WebhookTestModePanel webhookTestModePanel
	)
	{
		super(false);

		// Assign injected panels to class fields
		this.utilitiesPanel = utilitiesPanel;
		this.colosseumPanel = colosseumPanel;
		// this.colosseumReviewPanel = colosseumReviewPanel;
		this.itemsPanel = itemsPanel;
		this.itemsManagerPanel = itemsManagerPanel;
		this.webhookTestModePanel = webhookTestModePanel;

		this.setBorder(new EmptyBorder(10, 10, 10, 10));
		this.setBackground(ColorScheme.DARK_GRAY_COLOR);
		this.setLayout(new BorderLayout(0, 10));

		JComboBox<PanelViewMode> viewSelector = Components.createComboBox(PanelViewMode.values());

		JPanel topPanel = new JPanel(new BorderLayout());
		topPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		topPanel.add(viewSelector, BorderLayout.CENTER);

		cardLayout = new VisibleCardLayout();

		cardContainer = new ScrollableCardContainer(cardLayout, () -> !config.allowOuterScrollbar());
		cardContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);

		cardContainer.add(utilitiesPanel, PanelViewMode.UTILITIES.name());
		cardContainer.add(colosseumPanel, PanelViewMode.COLOSSEUM_STATISTICS.name());
		cardContainer.add(itemsPanel, PanelViewMode.ITEMS.name());
		cardContainer.add(itemsManagerPanel, PanelViewMode.ITEMS_MANAGER.name());
		cardContainer.add(webhookTestModePanel, PanelViewMode.WEBHOOK_TEST.name());


		viewSelector.addItemListener(e -> {
			if (e.getStateChange() == ItemEvent.SELECTED)
			{
				PanelViewMode selectedMode = (PanelViewMode) e.getItem();
				cardLayout.show(cardContainer, selectedMode.name());
				cardContainer.revalidate();
				cardContainer.repaint();
				String tooltipText;
				switch (selectedMode)
				{
					case COLOSSEUM_STATISTICS:
						tooltipText = "Panel in which various statistics can be viewed based on logged trials";
						break;
					case ITEMS:
						tooltipText = "Panel in which item data can be viewed";
						break;
					case ITEMS_MANAGER:
						tooltipText = "Panel in which item data can be viewed and deleted. Deletion can clear data related to an item you no longer possess.";
						break;
					case UTILITIES:
						tooltipText = "Panel with buttons to navigate to generated directories, test discord webhooks, manually export data or migrate data (if applicable).";
						break;
						default:
							tooltipText = "";
				}
				viewSelector.setToolTipText(tooltipText);
			}
		});

		scrollPane = wrapWithRuneLiteScrollbar(cardContainer);
		scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
//		scrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_NEVER);
		scrollPane.setPreferredSize(new Dimension(250, 1500));
		scrollPane.setMaximumSize(new Dimension(250, 1500));
		scrollPane.setAlignmentX(Component.LEFT_ALIGNMENT);

		// Set it such that it instantly scrolls to the top/bottom
		this.scrollBar = scrollPane.getVerticalScrollBar();
		this.scrollBar.setUnitIncrement(512);

		add(topPanel, BorderLayout.NORTH);
		add(scrollPane, BorderLayout.CENTER);
	}

	/**
	 * Updates the scroll speed of the outer scroll bar
	 */
	public void setOuterScrollSpeed(UIScrollSpeed scrollSpeed)
	{
		SwingUtilities.invokeLater(() -> {
			switch (scrollSpeed){
				case LOW:
					scrollBar.setUnitIncrement(32);
					break;
				case MEDIUM:
					scrollBar.setUnitIncrement(128);
					break;
				case HIGH:
					scrollBar.setUnitIncrement(512);
					break;
			}
		});
	}

	/**
	 * Updates the scroll speed of the inner scroll bars
	 */
	public void setInnerScrollSpeed(UIScrollSpeed scrollSpeed)
	{
		SwingUtilities.invokeLater(() -> {
			itemsPanel.setScrollSpeed(scrollSpeed);
			webhookTestModePanel.setScrollSpeed(scrollSpeed);
			itemsManagerPanel.setScrollSpeed(scrollSpeed);
			colosseumPanel.setScrollSpeed(scrollSpeed);
		});
	}

	public boolean canMigrateColosseumTrials()
	{
		return utilitiesPanel.getMigrationPanelExists();
	}

	/**
	 * Custom Scrollable JPanel.
	 * getScrollableTracksViewportWidth() returning TRUE forces child components
	 * to respect the panel width, preventing the horizontal scrollbar from triggering!
	 */
	private static class ScrollableCardContainer extends JPanel implements Scrollable
	{
		private final BooleanSupplier forceFitToScreen;
		public ScrollableCardContainer(CardLayout layout, BooleanSupplier forceFitToScreen) {
			super(layout);
			this.forceFitToScreen = forceFitToScreen;
		}

		@Override
		public Dimension getPreferredScrollableViewportSize() {
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) {
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction) {
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth() {
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight() {
			// If this returns true, Swing forces the panel to be exactly the height
			// of the visible screen space, completely eliminating the vertical scrollbar.
			return forceFitToScreen.getAsBoolean();
		}
	}

	/**
	 * Custom CardLayout that only sizes itself to the currently VISIBLE card,
	 * rather than the largest card in the entire deck.
	 */
	private static class VisibleCardLayout extends CardLayout
	{
		@Override
		public Dimension preferredLayoutSize(java.awt.Container parent) {
			for (Component comp : parent.getComponents()) {
				if (comp.isVisible()) {
					java.awt.Insets insets = parent.getInsets();
					Dimension pref = comp.getPreferredSize();
					pref.width += insets.left + insets.right;
					pref.height += insets.top + insets.bottom;
					return pref;
				}
			}
			return super.preferredLayoutSize(parent);
		}
	}
